      "suite-guided-field": "trường hướng dẫn bộ",
      "suite-guided-fields": "trường hướng dẫn bộ",
      "suite-guided-generic": "bộ hướng dẫn chung",
      "suite-guided-heading": "tiêu đề hướng dẫn bộ",
      "suite-guided-hidden-note": "ghi chú ẩn-hướng dẫn-bộ",
      "suite-guided-knn-compare": "suite-guided-knn-so sánh",
      "suite-guided-knn-extension": "phần mở rộng suite-guided-knn",
